import React, { useState, useEffect, useRef } from "react";
import styled, { createGlobalStyle } from "styled-components";
import { Light as SyntaxHighlighter } from "react-syntax-highlighter";
import { tomorrowNight } from "react-syntax-highlighter/dist/esm/styles/hljs";
import { motion, AnimatePresence } from "framer-motion";
import { FiCopy, FiDownload, FiMaximize2, FiPlay, FiSearch, FiTrash2 } from "react-icons/fi";

const GlobalStyle = createGlobalStyle`
  * { box-sizing: border-box; }
  html,body,#root { height:100%; }
  body {
    margin:0;
    font-family: -apple-system, BlinkMacSystemFont, "San Francisco", "Helvetica Neue", Arial;
    background: linear-gradient(180deg,#0b0f14 0%, #0b0e16 60%);
    color: #e6eef8;
    -webkit-font-smoothing:antialiased;
    -moz-osx-font-smoothing:grayscale;
    padding: 28px;
  }
`;

/* ---------- Styled ---------- */
const Shell = styled.div`
  max-width:1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 380px 1fr;
  gap: 28px;

  @media (max-width: 980px) {
    grid-template-columns: 1fr;
    padding-bottom: 120px;
  }
`;

const Sidebar = styled.div`
  background: rgba(255,255,255,0.03);
  border-radius: 16px;
  padding: 18px;
  min-height: 520px;
  box-shadow: 0 8px 30px rgba(2,6,23,0.75);
  border: 1px solid rgba(255,255,255,0.03);
`;

const Header = styled.div`
  display:flex;
  align-items:center;
  justify-content:space-between;
  margin-bottom:12px;
`;
const Title = styled.h1`
  font-size:18px;
  margin:0;
  letter-spacing: -0.2px;
`;

const Tiny = styled.div`
  color: #94a3b8;
  font-size:13px;
`;

const SearchRow = styled.div`
  display:flex;
  gap:8px;
  align-items:center;
  margin:12px 0 16px 0;
`;

const SearchInput = styled.input`
  flex:1;
  background: rgba(255,255,255,0.02);
  border: 1px solid rgba(255,255,255,0.03);
  padding:10px 12px;
  border-radius:10px;
  color: #e6eef8;
  outline:none;
  ::placeholder { color: #6b7684; }
`;

const ProgramList = styled.div`
  display:flex;
  flex-direction:column;
  gap:10px;
  margin-top:6px;
  max-height: 480px;
  overflow:auto;
  padding-right:6px;
`;

const ProgramCard = styled(motion.div)`
  background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));
  border-radius:12px;
  padding:12px;
  display:flex;
  gap:10px;
  align-items:flex-start;
  border: 1px solid rgba(255,255,255,0.03);
  cursor:pointer;
  &:hover { transform: translateY(-4px); }
`;

const ProgLeft = styled.div`
  width:52px;
  height:52px;
  border-radius:10px;
  display:flex;
  align-items:center;
  justify-content:center;
  background: linear-gradient(135deg,#101217, #141821);
  font-weight:700;
  color:#9fb7ff;
  font-size:15px;
  box-shadow: 0 6px 18px rgba(10,14,30,0.6);
`;

const ProgMeta = styled.div`
  flex:1;
`;

const ProgTitle = styled.div`
  font-size:14px;
  font-weight:700;
`;

const ProgDesc = styled.div`
  color:#94a3b8;
  font-size:13px;
  margin-top:6px;
`;

const Main = styled.div`
  background: rgba(255,255,255,0.02);
  border-radius: 16px;
  padding: 18px;
  min-height: 520px;
  box-shadow: 0 8px 30px rgba(2,6,23,0.75);
  border: 1px solid rgba(255,255,255,0.03);
  display:flex;
  flex-direction:column;
`;

const EditorRow = styled.div`
  display:grid;
  grid-template-columns: 1fr 420px;
  gap:14px;
  flex:1;
  min-height:340px;
  @media (max-width: 980px) { grid-template-columns: 1fr; }
`;

const EditorShell = styled.div`
  background: rgba(0,0,0,0.3);
  border-radius:12px;
  padding:12px;
  display:flex;
  flex-direction:column;
  height:100%;
`;

const Toolbar = styled.div`
  display:flex;
  align-items:center;
  gap:8px;
  margin-bottom:10px;
`;

const Button = styled.button`
  background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));
  border: 1px solid rgba(255,255,255,0.04);
  color: #e8f0ff;
  padding:8px 10px;
  border-radius:10px;
  cursor:pointer;
  display:inline-flex;
  gap:8px;
  align-items:center;
  font-size:13px;
  &:hover { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(0,0,0,0.45); }
`;

const Editor = styled.textarea`
  flex:1;
  resize:none;
  border: none;
  outline:none;
  background: transparent;
  color:#e6eef8;
  font-family: Menlo, Monaco, "Courier New", monospace;
  font-size:14px;
  line-height:1.5;
  padding:8px;
`;

const PreviewShell = styled.div`
  background: linear-gradient(180deg, rgba(255,255,255,0.01), rgba(255,255,255,0.02));
  border-radius:12px;
  padding:12px;
  height:100%;
  display:flex;
  flex-direction:column;
`;

const Small = styled.div`
  font-size:12px;
  color:#94a3b8;
`;

const BottomRow = styled.div`
  display:flex;
  justify-content:space-between;
  margin-top:12px;
  align-items:center;
`;

/* ---------- sample programs ---------- */
const SAMPLE = {
  14: {
    title: "Program 14 - Array Sum (C)",
    lang: "c",
    starter: `#include <stdio.h>

int main() {
    int n;
    printf("Enter n: ");
    scanf("%d", &n);
    int arr[n];
    int sum = 0;
    for (int i=0;i<n;i++){
        scanf("%d", &arr[i]);
        sum += arr[i];
    }
    printf("Sum = %d\\n", sum);
    return 0;
}
`,
  },
  15: {
    title: "Program 15 - Matrix Transpose (C)",
    lang: "c",
    starter: `#include <stdio.h>

int main() {
    int r,c;
    scanf("%d %d", &r, &c);
    int A[r][c];
    for(int i=0;i<r;i++)
      for(int j=0;j<c;j++)
        scanf("%d", &A[i][j]);

    for(int j=0;j<c;j++){
       for(int i=0;i<r;i++){
         printf("%d ", A[i][j]);
       }
       printf("\\n");
    }
    return 0;
}
`,
  },
  16: {
    title: "Program 16 - String Reverse (C)",
    lang: "c",
    starter: `#include <stdio.h>
#include <string.h>

int main() {
    char s[200];
    fgets(s, sizeof s, stdin);
    int n = strlen(s);
    if (s[n-1]=='\\n') s[n-1]='\\0', n--;
    for (int i=n-1;i>=0;i--) putchar(s[i]);
    putchar('\\n');
    return 0;
}
`,
  },
};

/* ---------- Helpers ---------- */
const encodeForShare = (text) => {
  return encodeURIComponent(btoa(unescape(encodeURIComponent(text))));
};
const decodeFromShare = (code) => {
  try {
    return decodeURIComponent(escape(atob(decodeURIComponent(code))));
  } catch {
    return "";
  }
};

export default function App() {
  const [programs, setPrograms] = useState([
    { id: 14, ...SAMPLE[14] },
    { id: 15, ...SAMPLE[15] },
    { id: 16, ...SAMPLE[16] },
  ]);
  const [activeId, setActiveId] = useState(14);
  const [contentMap, setContentMap] = useState(() => {
    // load from localStorage
    let stored = {};
    Object.keys(SAMPLE).forEach(k => {
      const key = `labcode_prog_${k}`;
      stored[k] = localStorage.getItem(key) ?? SAMPLE[k].starter;
    });
    return stored;
  });
  const [language, setLanguage] = useState("c");
  const [search, setSearch] = useState("");
  const [fullscreen, setFullscreen] = useState(false);
  const editorRef = useRef();
// Replace confirm usage with a state flag
const [confirmingId, setConfirmingId] = useState(null);

function handleDeleteProgram(id) {
  setConfirmingId(id);
}

function confirmDelete() {
  setPrograms(prev => prev.filter(p => p.id !== confirmingId));
  setContentMap(prev => {
    const copy = { ...prev };
    delete copy[confirmingId];
    return copy;
  });
  setConfirmingId(null);
}

  // apply content when active changes
  useEffect(() => {
    const prog = programs.find(p => p.id === activeId);
    setLanguage(prog?.lang ?? "c");
    // save to localStorage whenever contentMap changes handled elsewhere
  }, [activeId, programs]);

  // autosave contentMap to localStorage
  useEffect(() => {
    Object.entries(contentMap).forEach(([k, v]) => {
      localStorage.setItem(`labcode_prog_${k}`, v);
    });
  }, [contentMap]);

  // parse shared code from URL if present
  useEffect(() => {
    const u = new URL(window.location.href);
    const shared = u.searchParams.get("code");
    const pid = u.searchParams.get("pid");
    if (shared) {
      const raw = decodeFromShare(shared);
      if (raw) {
        if (pid && SAMPLE[pid]) {
          setContentMap(prev => ({ ...prev, [pid]: raw }));
          setActiveId(Number(pid));
        } else {
          // open as new temporary preview (we put into 99)
          setContentMap(prev => ({ ...prev, 99: raw }));
          setPrograms(prev => [{ id: 99, title: "Shared Snippet", lang: "c", starter: raw }, ...prev]);
          setActiveId(99);
        }
        // clean url (nice UX)
        window.history.replaceState({}, document.title, window.location.pathname);
      }
    }
  }, []);

  // Editor change handler
  function onChangeContent(v) {
    setContentMap(prev => ({ ...prev, [activeId]: v }));
  }

  // Copy to clipboard
  async function copyText(text) {
    try {
      await navigator.clipboard.writeText(text);
      toast("Copied!");
    } catch {
      toast("Copy failed — use Ctrl+C");
    }
  }

  function toast(msg) {
    // tiny toast no libs
    const t = document.createElement("div");
    t.textContent = msg;
    Object.assign(t.style, {
      position: "fixed",
      right: "20px",
      bottom: "20px",
      background: "#0b1220",
      color: "#dbeafe",
      padding: "10px 14px",
      borderRadius: "10px",
      border: "1px solid rgba(255,255,255,0.03)",
      boxShadow: "0 8px 30px rgba(2,6,23,0.6)",
      zIndex: 9999,
    });
    document.body.appendChild(t);
    setTimeout(() => { t.style.opacity = "0"; t.remove(); }, 1400);
  }

  function downloadFile(filename, text) {
    const el = document.createElement("a");
    const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
    el.href = URL.createObjectURL(blob);
    el.download = filename;
    document.body.appendChild(el);
    el.click();
    el.remove();
    URL.revokeObjectURL(el.href);
  }

  function handleNewProgram() {
    const newId = Math.floor(Math.random() * 9000) + 200;
    const newProg = { id: newId, title: `New Snippet ${newId}`, lang: "c", starter: "// paste code here\n" };
    setPrograms(prev => [newProg, ...prev]);
    setContentMap(prev => ({ ...prev, [newId]: newProg.starter }));
    setActiveId(newId);
    toast("New snippet created");
  }

  function handleDeleteProgram(id) {
    if (!confirm("Delete this snippet?")) return;
    setPrograms(prev => prev.filter(p => p.id !== id));
    setContentMap(prev => {
      const copy = { ...prev };
      delete copy[id];
      return copy;
    });
    if (activeId === id) setActiveId(programs[0]?.id ?? null);
  }

  // create share URL (small encode)
  function createShareUrl() {
    const text = contentMap[activeId] ?? "";
    const code = encodeForShare(text);
    const url = `${window.location.origin}${window.location.pathname}?code=${code}&pid=${activeId}`;
    copyText(url);
    toast("Share link copied");
  }

  const filtered = programs.filter(p => {
    if (!search) return true;
    const s = search.toLowerCase();
    return p.title.toLowerCase().includes(s) || (p.starter && p.starter.toLowerCase().includes(s));
  });

  const activeContent = contentMap[activeId] ?? SAMPLE[activeId]?.starter ?? "";

  return (
    <>
      <GlobalStyle />
      <Shell>
        <Sidebar>
          <Header>
            <div>
              <Title>LabCodeBox</Title>
              <Tiny>Paste — run — submit. Dark Apple vibes.</Tiny>
            </div>
            <div>
              <Small>Theme: <strong>Dark</strong></Small>
            </div>
          </Header>

          <SearchRow>
            <SearchInput
              placeholder="Search programs or code..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            <Button onClick={handleNewProgram} title="Create new snippet"><FiPlay /></Button>
          </SearchRow>

          <ProgramList>
            <AnimatePresence initial={false}>
              {filtered.map(p => (
                <ProgramCard
                  key={p.id}
                  layout
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 8 }}
                  onClick={() => setActiveId(p.id)}
                  style={{ border: activeId === p.id ? "1px solid rgba(95,160,255,0.22)" : undefined }}
                >
                  <ProgLeft>{p.id}</ProgLeft>
                  <ProgMeta>
                    <ProgTitle>{p.title}</ProgTitle>
                    <ProgDesc>{(p.starter || "").split("\n").slice(0,2).join(" ").slice(0,80)}</ProgDesc>
                    <div style={{ marginTop:8, display:"flex", gap:8 }}>
                      <Button onClick={(ev) => { ev.stopPropagation(); setContentMap(prev => ({ ...prev, [p.id]: SAMPLE[p.id]?.starter ?? prev[p.id] ?? "// blank" })); toast("Reset to starter"); }}>Reset</Button>
                      <Button onClick={(ev) => { ev.stopPropagation(); handleDeleteProgram(p.id); }}><FiTrash2 /></Button>
                    </div>
                  </ProgMeta>
                </ProgramCard>
              ))}
            </AnimatePresence>
          </ProgramList>

          <div style={{ marginTop: 14 }}>
            <Small>Tips</Small>
            <div style={{ color:"#94a3b8", fontSize:13, marginTop:6 }}>
              • Paste code on the left. Use copy/download to submit. <br/>
              • Use the share button to copy a short URL of your snippet. <br/>
              • Snippets saved locally (browser storage).
            </div>
          </div>
        </Sidebar>

        <Main>
          <Header>
            <div>
              <Title>{programs.find(p=>p.id===activeId)?.title ?? "Untitled"}</Title>
              <Tiny>Active snippet ID: {activeId}</Tiny>
            </div>
            <div style={{ display:"flex", gap:8, alignItems:"center" }}>
              <Small>Lang:</Small>
              <select value={language} onChange={(e) => setLanguage(e.target.value)} style={{ background:"transparent", border:"1px solid rgba(255,255,255,0.03)", color:"#e6eef8", padding:"6px 8px", borderRadius:8 }}>
                <option value="c">C</option>
                <option value="cpp">C++</option>
                <option value="java">Java</option>
                <option value="python">Python</option>
                <option value="js">JavaScript</option>
              </select>
            </div>
          </Header>

          <EditorRow>
            <EditorShell style={ fullscreen ? { gridColumn: "1 / -1", height: "680px" } : {} }>
              <Toolbar>
                <Button onClick={() => { copyText(activeContent); }}><FiCopy /> Copy</Button>
                <Button onClick={() => {
                  downloadFile(`program_${activeId}.txt`, activeContent);
                }}><FiDownload /> Download</Button>
                <Button onClick={() => { setFullscreen(f => !f); }}><FiMaximize2 /> {fullscreen ? "Exit" : "Fullscreen"}</Button>
                <Button onClick={() => { createShareUrl(); }}>Share</Button>

                <div style={{ flex:1 }} />

                <Button onClick={() => {
                  // quick run simulation: highlight compile errors? (toy)
                  toast("Run: This is a preview-only lab box (no compilation).");
                }}><FiPlay /> Run (preview)</Button>
              </Toolbar>

              <Editor
                ref={editorRef}
                value={activeContent}
                onChange={(e) => onChangeContent(e.target.value)}
                placeholder="// Paste your code here. Autosaved."
                spellCheck="false"
              />
            </EditorShell>

            <PreviewShell>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8 }}>
                <Small>Preview</Small>
                <div style={{ display:"flex", gap:8 }}>
                  <Button onClick={() => copyText(activeContent)} title="Copy preview"><FiCopy /></Button>
                  <Button onClick={() => downloadFile(`program_${activeId}.${language === 'python' ? 'py' : language === 'js' ? 'js' : 'c'}`, activeContent)}><FiDownload /></Button>
                </div>
              </div>

              <div style={{ flex:1, overflow:"auto", borderRadius:8 }}>
                <SyntaxHighlighter
                  language={language === "js" ? "javascript" : language}
                  style={tomorrowNight}
                  showLineNumbers
                  wrapLongLines
                >
                  {activeContent}
                </SyntaxHighlighter>
              </div>

              <BottomRow>
                <Small>Autosaved locally • {new Date().toLocaleTimeString()}</Small>
                <div style={{ display:"flex", gap:8 }}>
                  <Button onClick={() => { setContentMap(prev => ({ ...prev, [activeId]: SAMPLE[activeId]?.starter ?? "" })); toast("Reset to starter code"); }}>Reset to starter</Button>
                </div>
              </BottomRow>
            </PreviewShell>
          </EditorRow>
        </Main>
      </Shell>
    </>
  );
}
